<?php

declare(strict_types=1);
namespace StageArtCore\Domain\Production;
final class ProductionValidator{public function validate(array$post):void{$this->dateRange($post);$this->releases($post);$this->performances((array)($post['performances']??[]));$this->labels((array)($post['labels']??[]));$this->tickets((array)($post['tickets']??[]));$this->credits((array)($post['credits']??[]));}private function dateRange(array$post):void{$start=trim((string)($post['schedule_start']??''));$end=trim((string)($post['schedule_end']??''));if($start!==''&&!$this->validDate($start))$this->fail('公演日程の開始日は正しい日付を入力してください。');if($end!==''&&!$this->validDate($end))$this->fail('公演日程の終了日は正しい日付を入力してください。');if($start!==''&&$end!==''&&$start>$end)$this->fail('公演日程の終了日は開始日以降にしてください。');}private function releases(array$post):void{$keys=['main_image_release','summary_release','description_release','schedule_release','performance_release','venue_release','venue_map_release','cast_release','staff_release','ticket_release'];foreach($keys as$key){$value=trim((string)($post[$key]??''));if($value!==''&&$this->toUtc($value)===null)$this->fail('情報解禁日時が正しくありません: '.$key);}}private function performances(array$rows):void{$seen=[];foreach($rows as$row){if(!is_array($row))continue;$date=trim((string)($row['date']??''));$start=trim((string)($row['start']??''));$end=trim((string)($row['end']??''));if($date===''&&$start===''&&$end==='')continue;if(!$this->validDate($date))$this->fail('公演回の開催日は正しい日付を入力してください。');if(!$this->validTime($start))$this->fail('公演回の開演時刻が正しくありません。');if($end!==''&&!$this->validTime($end))$this->fail('公演回の終演予定時刻が正しくありません。');if($end!==''&&$end<=$start)$this->fail('公演回の終演予定時刻は開演時刻より後にしてください。');$key=$date.' '.$start;if(isset($seen[$key]))$this->fail('同じ開催日の同じ開演時刻の公演回が重複しています: '.$key);$seen[$key]=true;}}private function labels(array$rows):void{$symbols=[];foreach($rows as$row){if(!is_array($row))continue;$symbol=trim((string)($row['symbol']??''));if($symbol==='')continue;if(isset($symbols[$symbol]))$this->fail('公演回ラベルの記号が重複しています: '.$symbol);$symbols[$symbol]=true;}}private function tickets(array$rows):void{foreach($rows as$row){if(!is_array($row))continue;$name=trim((string)($row['description']??''));if($name==='')continue;$amount=(string)($row['amount']??'0');if(!preg_match('/^\d+$/',$amount))$this->fail('チケット料金は0以上の整数で入力してください。');}}private function credits(array$sections):void{foreach($sections as$section){if(!is_array($section))continue;if(trim((string)($section['name']??''))==='')continue;$release=trim((string)($section['release_at']??''));if($release!==''&&$this->toUtc($release)===null)$this->fail('クレジット区分の情報解禁日時が正しくありません。');foreach((array)($section['items']??[]) as$item){if(!is_array($item))continue;$url=trim((string)($item['url']??''));if($url!==''&&!wp_http_validate_url($url))$this->fail('クレジットのリンクURLが正しくありません。');}}}private function validDate(string$value):bool{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$value))return false;[$y,$m,$d]=array_map('intval',explode('-',$value));return checkdate($m,$d,$y);}private function validTime(string$value):bool{return(bool)preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$value);}private function toUtc(string$value):?string{$value=str_replace('T',' ',trim($value));$d=\DateTimeImmutable::createFromFormat('Y-m-d H:i',$value,new \DateTimeZone('Asia/Tokyo'));if(!$d||$d->format('Y-m-d H:i')!==$value)return null;return$d->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s');}private function fail(string$message):never{wp_die(esc_html($message),'公演情報の入力エラー',['response'=>400]);}}
